import os
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def extract_key_value_pairs(
    document_bytes: bytes,
    region_name: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """
    Extract key-value pairs from a form-like document using Amazon Textract.

    Args:
        document_bytes: Binary contents of the document (PDF, PNG, JPG, TIFF).
        region_name: Optional AWS region for Textract.

    Returns:
        A list of dictionaries with keys:
            - key: extracted field name
            - value: extracted field value
            - confidence: optional confidence score if available
    """
    textract_kwargs: Dict[str, Any] = {}
    if region_name:
        textract_kwargs["region_name"] = region_name

    client = boto3.client("textract", **textract_kwargs)

    try:
        response = client.analyze_document(
            Document={"Bytes": document_bytes},
            FeatureTypes=["FORMS"],
        )
    except (BotoCoreError, ClientError):
        return []

    blocks = response.get("Blocks", [])
    block_map = {block.get("Id"): block for block in blocks if "Id" in block}

    def _get_text_from_relationships(block: Dict[str, Any]) -> str:
        texts: List[str] = []
        for rel in block.get("Relationships", []):
            if rel.get("Type") != "CHILD":
                continue
            for child_id in rel.get("Ids", []):
                child = block_map.get(child_id)
                if not child:
                    continue
                if child.get("BlockType") == "WORD":
                    txt = child.get("Text")
                    if txt:
                        texts.append(txt)
                elif child.get("BlockType") == "SELECTION_ELEMENT" and child.get("SelectionStatus") == "SELECTED":
                    texts.append("X")
        return " ".join(texts).strip()

    key_blocks = [b for b in blocks if b.get("BlockType") == "KEY_VALUE_SET" and "KEY" in b.get("EntityTypes", [])]
    results: List[Dict[str, Any]] = []

    for key_block in key_blocks:
        key_text = _get_text_from_relationships(key_block)

        value_text = ""
        confidence = key_block.get("Confidence")

        for rel in key_block.get("Relationships", []):
            if rel.get("Type") != "VALUE":
                continue
            for value_id in rel.get("Ids", []):
                value_block = block_map.get(value_id)
                if not value_block:
                    continue
                value_text = _get_text_from_relationships(value_block)
                if value_block.get("Confidence") is not None:
                    confidence = value_block.get("Confidence")
                break
            if value_text:
                break

        if key_text or value_text:
            results.append(
                {
                    "key": key_text,
                    "value": value_text,
                    "confidence": confidence,
                }
            )

    return results


def extract_from_file(path: str, region_name: Optional[str] = None) -> List[Dict[str, Any]]:
    with open(path, "rb") as f:
        return extract_key_value_pairs(f.read(), region_name=region_name)


if __name__ == "__main__":
    import json
    import sys

    if len(sys.argv) < 2:
        raise SystemExit("Usage: python script.py <document_path>")

    region = os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")
    extracted = extract_from_file(sys.argv[1], region_name=region)
    print(json.dumps(extracted, indent=2, ensure_ascii=False))
